// CI-ONLY: temporary, explicitly opted-in Next.js route for the real
// Rust -> Caddy mTLS -> Spring/JPA/PG18 -> authorized browser acceptance.
// Never committed under src/app and never generated by a normal product build.
import { existsSync, mkdirSync, writeFileSync } from 'node:fs';
import { basename, join, resolve } from 'node:path';

const required = [
  'LANVERIQ_SYNTHETIC_CADDY_BRIDGE',
  'LANVERIQ_SYNTHETIC_LINUX_CSR',
  'LANVERIQ_SYNTHETIC_AGENT_BUSINESS_LOOP',
  'LANVERIQ_SYNTHETIC_CONSOLE_SESSION',
  'LANVERIQ_SYNTHETIC_CHAIN_READ',
  'LANVERIQ_SYNTHETIC_CHAIN_UI',
  'LANVERIQ_SYNTHETIC_BROWSER_PROBE',
  'LANVERIQ_SYNTHETIC_NEXTJS_PROBE',
];
if (process.env.GITHUB_ACTIONS !== 'true' ||
    process.env.RUNNER_OS !== 'Linux' ||
    required.some(key => process.env[key] !== '1') ||
    process.env.LANVERIQ_SYNTHETIC_AUTH_UI_PROBE !== '0' ||
    process.env.LANVERIQ_SYNTHETIC_MULTI_ADMIN_PROBE !== '0' ||
    basename(process.cwd()) !== 'web') {
  throw new Error('Refusing Rust-to-Next.js fixture outside exact disposable CI scope');
}

const root = resolve(process.cwd());
const source = join(root, 'src/staged-console-workspace.tsx');
const dir = join(root, 'src/app/synthetic-rust-chain');
const page = join(dir, 'page.tsx');
if (!existsSync(source) || existsSync(dir) || existsSync(page)) {
  throw new Error('Missing shared product candidate or existing test-only route');
}
mkdirSync(dir, { mode: 0o700 });
writeFileSync(page, `// Disposable CI only. Never commit this route to the product.
import { StagedConsoleWorkspace } from '@/staged-console-workspace';
export const dynamic = 'force-dynamic';
export default function SyntheticRustChainPage() {
  return <StagedConsoleWorkspace />;
}
`, { encoding: 'utf8', mode: 0o600, flag: 'wx' });
console.log('CI-only synthetic Rust-to-Next.js page installed; no product route changed');
